function t(j1,j2,j3) result(res)
  use, intrinsic :: iso_c_binding
  use types
  use mxpart_mod
  use sprods_com_mod

  implicit none

  integer(c_int), intent(in) :: j1, j2, j3
  real(c_double) :: res

  interface
    function t_wrapper(j1,j2,j3) bind(C, name="t_wrapper")
      import :: c_int, c_double
      integer(c_int), value :: j1, j2, j3
      real(c_double) :: t_wrapper
    end function t_wrapper
  end interface

  res = t_wrapper(j1,j2,j3)
end function t
