#include <W1jet.hpp>
#include <cmath>
#include <complex>
#include <mxpart_mod.hpp>
#include <sprods_com_mod.hpp>

using namespace mxpart_mod;
using namespace sprods_com_mod;

double t(int j1, int j2, int j3) {
  double t_value = s(j1, j2) + s(j2, j3) + s(j1, j3);
  return t_value;
}

extern "C" {
  double t_wrapper(int j1, int j2, int j3) {
    return t(j1, j2, j3);
  }
}

